/// Adds durable source checksums to the existing migration ledger. The
/// backfill is performed by the transactional migrator after it has validated
/// the legacy identity prefix; this body only changes the ledger shape.
const MIGRATION_CHECKSUMS_MIGRATION_SCHEMA: &str = r"
ALTER TABLE schema_migrations ADD COLUMN source_checksum TEXT NOT NULL DEFAULT '';
";

/// Source-owned whole-deployment identity. The singleton witness makes an
/// empty resource relation explicit; the immutable child rows carry the
/// complete pack/resource set and are checked against the witness digest.
const DEPLOYMENT_IDENTITIES_MIGRATION_SCHEMA: &str = r"
CREATE TABLE deployment_identity_metadata (
    metadata_id INTEGER PRIMARY KEY CHECK (metadata_id = 1),
    pack_set_digest BLOB NOT NULL CHECK (length(pack_set_digest) = 32),
    resource_set_digest BLOB NOT NULL CHECK (length(resource_set_digest) = 32),
    canonical_bytes BLOB NOT NULL,
    CHECK (length(canonical_bytes) > 0)
) STRICT;
CREATE TABLE deployment_pack_identities (
    pack_id TEXT NOT NULL,
    revision TEXT NOT NULL,
    pack_digest BLOB NOT NULL CHECK (length(pack_digest) = 32),
    PRIMARY KEY (pack_id, revision)
) STRICT;
CREATE TABLE deployment_resource_identities (
    resource_kind TEXT NOT NULL CHECK (resource_kind IN ('artifact', 'codec', 'schema')),
    resource_identity TEXT NOT NULL,
    size_bytes INTEGER NOT NULL CHECK (size_bytes BETWEEN 0 AND 16777216),
    resource_digest BLOB NOT NULL CHECK (length(resource_digest) = 32),
    PRIMARY KEY (resource_kind, resource_identity)
) STRICT;
CREATE TRIGGER deployment_identity_metadata_immutable_update
BEFORE UPDATE ON deployment_identity_metadata BEGIN
    SELECT RAISE(ABORT, 'deployment identity metadata is immutable');
END;
CREATE TRIGGER deployment_identity_metadata_immutable_delete
BEFORE DELETE ON deployment_identity_metadata BEGIN
    SELECT RAISE(ABORT, 'deployment identity metadata is immutable');
END;
CREATE TRIGGER deployment_pack_identity_immutable_update
BEFORE UPDATE ON deployment_pack_identities BEGIN
    SELECT RAISE(ABORT, 'deployment pack identity is immutable');
END;
CREATE TRIGGER deployment_pack_identity_immutable_delete
BEFORE DELETE ON deployment_pack_identities BEGIN
    SELECT RAISE(ABORT, 'deployment pack identity is immutable');
END;
CREATE TRIGGER deployment_resource_identity_immutable_update
BEFORE UPDATE ON deployment_resource_identities BEGIN
    SELECT RAISE(ABORT, 'deployment resource identity is immutable');
END;
CREATE TRIGGER deployment_resource_identity_immutable_delete
BEFORE DELETE ON deployment_resource_identities BEGIN
    SELECT RAISE(ABORT, 'deployment resource identity is immutable');
END;
";

/// Adds the durable byte relations required by whole-deployment transfer and
/// restore. Resource metadata remains the source-authoritative identity set;
/// the child rows retain the exact content it names. Integrity incidents are
/// append-only evidence and are deliberately distinct from the current Room
/// integrity disposition.
const TRANSFER_RECOVERY_COMPLETENESS_MIGRATION_SCHEMA: &str = r"
CREATE TABLE deployment_resource_blobs (
    resource_kind TEXT NOT NULL CHECK (resource_kind IN ('artifact', 'codec', 'schema')),
    resource_identity TEXT NOT NULL,
    resource_bytes BLOB NOT NULL CHECK (length(resource_bytes) <= 16777216),
    resource_digest BLOB NOT NULL CHECK (length(resource_digest) = 32),
    PRIMARY KEY (resource_kind, resource_identity),
    FOREIGN KEY (resource_kind, resource_identity)
        REFERENCES deployment_resource_identities(resource_kind, resource_identity)
        ON DELETE RESTRICT
) STRICT;
CREATE TABLE integrity_incidents (
    room_id TEXT NOT NULL REFERENCES rooms(room_id) ON DELETE CASCADE,
    incident_seq INTEGER NOT NULL CHECK (incident_seq BETWEEN 1 AND 9007199254740991),
    generation INTEGER NOT NULL CHECK (generation BETWEEN 1 AND 9007199254740991),
    status TEXT NOT NULL CHECK (status IN ('healthy', 'faulted', 'quarantined')),
    reason_code TEXT NOT NULL,
    details_bytes BLOB,
    PRIMARY KEY (room_id, incident_seq)
) STRICT;
CREATE TRIGGER deployment_resource_blob_immutable_update
BEFORE UPDATE ON deployment_resource_blobs BEGIN
    SELECT RAISE(ABORT, 'deployment resource bytes are immutable');
END;
CREATE TRIGGER deployment_resource_blob_immutable_delete
BEFORE DELETE ON deployment_resource_blobs BEGIN
    SELECT RAISE(ABORT, 'deployment resource bytes are immutable');
END;
CREATE TRIGGER integrity_incident_immutable_update
BEFORE UPDATE ON integrity_incidents BEGIN
    SELECT RAISE(ABORT, 'integrity incident is immutable');
END;
CREATE TRIGGER integrity_incident_immutable_delete
BEFORE DELETE ON integrity_incidents BEGIN
    SELECT RAISE(ABORT, 'integrity incident is immutable');
END;
";

/// Adds the source-owned transfer authority state and closes resource
/// identities across kinds. The singleton begins source-authoritative; only
/// the controlled writer may move it through pending to permanently retired.
const TRANSFER_LIFECYCLE_MIGRATION_SCHEMA: &str = r"
CREATE UNIQUE INDEX deployment_resource_identity_global_v1
    ON deployment_resource_identities(resource_identity);
CREATE UNIQUE INDEX deployment_resource_blob_identity_global_v1
    ON deployment_resource_blobs(resource_identity);
CREATE TABLE source_transfer_lifecycle (
    lifecycle_id INTEGER PRIMARY KEY CHECK (lifecycle_id = 1),
    state TEXT NOT NULL CHECK (state IN ('source_authoritative', 'transfer_pending', 'source_retired')),
    source_epoch INTEGER CHECK (source_epoch BETWEEN 1 AND 9007199254740991),
    target_epoch INTEGER CHECK (target_epoch BETWEEN 2 AND 9007199254740991),
    backup_path TEXT,
    backup_digest BLOB CHECK (backup_digest IS NULL OR length(backup_digest) = 32),
    bundle_hash BLOB CHECK (bundle_hash IS NULL OR length(bundle_hash) = 32),
    target_fingerprint BLOB CHECK (target_fingerprint IS NULL OR length(target_fingerprint) = 32),
    last_aborted_bundle_hash BLOB
        CHECK (last_aborted_bundle_hash IS NULL OR length(last_aborted_bundle_hash) = 32),
    last_aborted_target_fingerprint BLOB
        CHECK (last_aborted_target_fingerprint IS NULL OR length(last_aborted_target_fingerprint) = 32),
    CHECK (
        (state = 'source_authoritative' AND source_epoch IS NULL AND target_epoch IS NULL
            AND backup_path IS NULL AND backup_digest IS NULL
            AND bundle_hash IS NULL AND target_fingerprint IS NULL)
        OR
        (state = 'transfer_pending'
            AND source_epoch IS NOT NULL AND target_epoch = source_epoch + 1
            AND backup_path IS NOT NULL AND length(backup_path) > 0
            AND backup_digest IS NOT NULL
            AND ((bundle_hash IS NULL AND target_fingerprint IS NULL)
                OR (bundle_hash IS NOT NULL AND target_fingerprint IS NOT NULL)))
        OR
        (state = 'source_retired'
            AND source_epoch IS NOT NULL AND target_epoch = source_epoch + 1
            AND backup_path IS NOT NULL AND length(backup_path) > 0
            AND backup_digest IS NOT NULL
            AND bundle_hash IS NOT NULL AND target_fingerprint IS NOT NULL)
    ),
    CHECK (
        (last_aborted_bundle_hash IS NULL AND last_aborted_target_fingerprint IS NULL)
        OR (last_aborted_bundle_hash IS NOT NULL
            AND last_aborted_target_fingerprint IS NOT NULL)
    ),
    CHECK (state = 'source_authoritative'
        OR (last_aborted_bundle_hash IS NULL AND last_aborted_target_fingerprint IS NULL))
) STRICT;
INSERT INTO source_transfer_lifecycle(lifecycle_id, state)
VALUES (1, 'source_authoritative');
";

/// Persists the exact storage object created for a source-transfer backup.
/// Fixed-width lowercase hexadecimal keeps the full Unix or Windows identity
/// lossless without relying on `SQLite`'s signed 64-bit integer representation.
const TRANSFER_BACKUP_IDENTITY_MIGRATION_SCHEMA: &str = r"
ALTER TABLE source_transfer_lifecycle ADD COLUMN backup_storage_id TEXT
    CHECK (backup_storage_id IS NULL OR (
        length(backup_storage_id) = 16
        AND backup_storage_id = lower(backup_storage_id)
        AND backup_storage_id NOT GLOB '*[^0-9a-f]*'
    ));
ALTER TABLE source_transfer_lifecycle ADD COLUMN backup_file_id TEXT
    CHECK (backup_file_id IS NULL OR (
        length(backup_file_id) = 32
        AND backup_file_id = lower(backup_file_id)
        AND backup_file_id NOT GLOB '*[^0-9a-f]*'
    ));
CREATE TRIGGER source_transfer_backup_identity_insert_v1
BEFORE INSERT ON source_transfer_lifecycle
WHEN (NEW.state = 'source_authoritative'
        AND (NEW.backup_storage_id IS NOT NULL OR NEW.backup_file_id IS NOT NULL))
    OR (NEW.state <> 'source_authoritative'
        AND (NEW.backup_storage_id IS NULL OR NEW.backup_file_id IS NULL))
BEGIN
    SELECT RAISE(ABORT, 'source transfer backup identity shape');
END;
CREATE TRIGGER source_transfer_backup_identity_update_v1
BEFORE UPDATE ON source_transfer_lifecycle
WHEN (NEW.state = 'source_authoritative'
        AND (NEW.backup_storage_id IS NOT NULL OR NEW.backup_file_id IS NOT NULL))
    OR (NEW.state <> 'source_authoritative'
        AND (NEW.backup_storage_id IS NULL OR NEW.backup_file_id IS NULL))
BEGIN
    SELECT RAISE(ABORT, 'source transfer backup identity shape');
END;
";

/// Retains the host-owned semantic time sampled for the first preparation of
/// one exact `ExternalInput` operation identity across retry and restart.
