impl SqlitePreparedWrite {
    fn from_core(prepared: &PreparedRoomWriteV1) -> Result<Self, ()> {
        let identity = prepared.identity().clone();
        let identity_bytes = identity.canonical_bytes().map_err(|_| ())?;
        let request_hash = prepared.request_hash().clone();
        let (authority, stored_result, branch) = match prepared {
            PreparedRoomWriteV1::Create(create) => (
                create.authority_witness().clone(),
                create.semantic_result().clone(),
                PreparedSqliteBranch::Create(Box::new(create.persistence().clone())),
            ),
            PreparedRoomWriteV1::Existing(existing) => (
                existing.authority_witness().clone(),
                existing.semantic_result().clone(),
                PreparedSqliteBranch::Existing {
                    basis: Box::new(existing.basis_complete_head().clone()),
                    integrity_generation: existing.integrity_generation(),
                    input_witness: existing.input_witness().clone(),
                    intent: existing.intent().clone(),
                },
            ),
        };
        if stored_result.operation_identity() != &identity
            || stored_result.canonical_request_hash() != &request_hash
        {
            return Err(());
        }
        let receipt = PreparedReceiptRow {
            room_id: stored_result.target_room_id().to_string(),
            operation_kind: identity.operation_kind(),
            basis_head_bytes: stored_result.canonical_basis_head_bytes().map_err(|_| ())?,
            semantic_input_bytes: stored_result
                .semantic_input()
                .canonical_bytes()
                .map_err(|_| ())?,
            semantic_time_bytes: stored_result
                .canonical_semantic_time_bytes()
                .map_err(|_| ())?,
            resolution_kind: stored_result.resolution_kind(),
            transition_seq: stored_result
                .transition_seq()
                .map(|sequence| i64::try_from(sequence.get()).map_err(|_| ()))
                .transpose()?,
            stored_result,
        };
        Ok(Self {
            identity,
            identity_bytes,
            request_hash,
            authority,
            receipt,
            branch,
        })
    }

    fn post_commit_snapshot(&self) -> Option<PostCommitSnapshotV1> {
        let persistence = match &self.branch {
            PreparedSqliteBranch::Create(persistence) => SnapshotPersistence::Create(persistence),
            PreparedSqliteBranch::Existing {
                intent: PreparedExistingIntentV1::Advance(advance),
                ..
            } => SnapshotPersistence::Advance(advance),
            PreparedSqliteBranch::Existing {
                intent: PreparedExistingIntentV1::DurableDisposition,
                ..
            } => return None,
        };
        Some(PostCommitSnapshotV1::from_persistence(&persistence))
    }

    fn snapshot_cadence_candidate(&self) -> Option<SnapshotCadenceCandidate<'_>> {
        match &self.branch {
            PreparedSqliteBranch::Create(persistence) => Some(SnapshotCadenceCandidate {
                room_id: persistence.complete_head.room_id().as_str(),
                room_seq: 0,
                genesis: true,
            }),
            PreparedSqliteBranch::Existing {
                intent: PreparedExistingIntentV1::Advance(advance),
                ..
            } => Some(SnapshotCadenceCandidate {
                room_id: advance.resulting_complete_head.room_id().as_str(),
                room_seq: i64::try_from(advance.resulting_complete_head.room_seq().get())
                    .unwrap_or_else(|_| unreachable!("prepared Room sequence is safe for SQLite")),
                genesis: false,
            }),
            PreparedSqliteBranch::Existing {
                intent: PreparedExistingIntentV1::DurableDisposition,
                ..
            } => None,
        }
    }
}

enum SnapshotPersistence<'a> {
    Create(&'a PreparedCreationPersistenceV1),
    Advance(&'a PreparedAdvancePersistenceV1),
}

impl PostCommitSnapshotV1 {
    fn from_persistence(persistence: &SnapshotPersistence<'_>) -> Self {
        let (head, head_bytes, core_bytes, activity_bytes) = match persistence {
            SnapshotPersistence::Create(value) => (
                &value.complete_head,
                &value.canonical_head_bytes,
                &value.canonical_core_state_bytes,
                &value.canonical_activity_state_bytes,
            ),
            SnapshotPersistence::Advance(value) => (
                &value.resulting_complete_head,
                &value.canonical_resulting_head_bytes,
                &value.canonical_resulting_core_state_bytes,
                &value.canonical_resulting_activity_state_bytes,
            ),
        };
        Self {
            room_id: head.room_id().to_string(),
            room_seq: i64::try_from(head.room_seq().get())
                .unwrap_or_else(|_| unreachable!("prepared Room sequence is safe for SQLite")),
            genesis_or_transition_hash: head.genesis_or_transition_hash().to_string(),
            core_schema_version: head.core_schema_version().to_owned(),
            pack_digest: head.pack_digest().to_string(),
            core_state_hash: head.core_state_hash().to_string(),
            activity_state_hash: head.activity_state_hash().to_string(),
            authoritative_state_hash: head.authoritative_state_hash().to_string(),
            complete_head_bytes: head_bytes.clone(),
            core_state_bytes: core_bytes.clone(),
            activity_state_bytes: activity_bytes.clone(),
        }
    }
}

