    #[cfg(unix)]
    #[test]
    fn retained_writer_rejects_path_substitution_before_vfs_open() {
        let directory = tempdir().unwrap_or_else(|error| panic!("temp directory: {error}"));
        let root = fs::canonicalize(directory.path())
            .unwrap_or_else(|error| panic!("canonical temp directory: {error}"));
        let source = root.join("source.sqlite3");
        let held = root.join("held-source.sqlite3");
        let replacement = root.join("replacement.sqlite3");
        drop(
            SqliteRoomStore::open(&source).unwrap_or_else(|error| panic!("create source: {error}")),
        );
        drop(
            SqliteRoomStore::open(&replacement)
                .unwrap_or_else(|error| panic!("create replacement: {error}")),
        );
        let retained = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(&source)
            .unwrap_or_else(|error| panic!("retain source: {error}"));
        let hook_source = source.clone();
        let hook_held = held.clone();
        let hook_replacement = replacement.clone();
        arm_writer_exact_open_hook(&source, move || {
            fs::rename(&hook_source, &hook_held)?;
            fs::rename(&hook_replacement, &hook_source)
        });

        let result = SqliteRoomStore::open_with_retained_file(&source, retained);
        assert!(matches!(
            result,
            Err(SqliteStoreOpenError::ExactOpen(
                worldstream_sqlite_open::ExactSqliteOpenError::MainDatabaseIdentityMismatch
            ))
        ));
        assert_eq!(
            Connection::open(&held)
                .and_then(|connection| connection
                    .query_row("PRAGMA integrity_check", (), |row| row.get::<_, String>(0)))
                .unwrap_or_else(|error| panic!("held source integrity: {error}")),
            "ok"
        );
        assert_eq!(
            Connection::open(&source)
                .and_then(|connection| connection
                    .query_row("PRAGMA integrity_check", (), |row| row.get::<_, String>(0)))
                .unwrap_or_else(|error| panic!("replacement integrity: {error}")),
            "ok"
        );
    }

    #[cfg(unix)]
    #[test]
    fn post_start_database_substitution_fails_reads_and_the_next_write_closed() {
        fn sidecar(path: &Path, suffix: &str) -> PathBuf {
            let mut value = path.as_os_str().to_owned();
            value.push(suffix);
            PathBuf::from(value)
        }

        let source_directory =
            tempdir().unwrap_or_else(|error| panic!("source directory: {error}"));
        let replacement_directory =
            tempdir().unwrap_or_else(|error| panic!("replacement directory: {error}"));
        let source = fs::canonicalize(source_directory.path())
            .unwrap_or_else(|error| panic!("canonical source directory: {error}"))
            .join("database.sqlite3");
        let held = source.with_file_name("held-database.sqlite3");
        let replacement = fs::canonicalize(replacement_directory.path())
            .unwrap_or_else(|error| panic!("canonical replacement directory: {error}"))
            .join("replacement.sqlite3");

        let store = SqliteRoomStore::open(&source)
            .unwrap_or_else(|error| panic!("open retained source: {error}"));
        let original_identity = store.database_identity();
        let replacement_store = SqliteRoomStore::open(&replacement)
            .unwrap_or_else(|error| panic!("open replacement: {error}"));
        seed_real_host_authority(&replacement_store);
        let replacement_identity = replacement_store.database_identity();
        drop(replacement_store);

        fs::rename(&source, &held)
            .unwrap_or_else(|error| panic!("retain original database name: {error}"));
        for suffix in ["-wal", "-shm"] {
            let original_sidecar = sidecar(&source, suffix);
            if original_sidecar.exists() {
                fs::rename(&original_sidecar, sidecar(&held, suffix))
                    .unwrap_or_else(|error| panic!("retain original {suffix}: {error}"));
            }
        }
        fs::rename(&replacement, &source)
            .unwrap_or_else(|error| panic!("install replacement database: {error}"));
        for suffix in ["-wal", "-shm"] {
            let replacement_sidecar = sidecar(&replacement, suffix);
            if replacement_sidecar.exists() {
                fs::rename(&replacement_sidecar, sidecar(&source, suffix))
                    .unwrap_or_else(|error| panic!("install replacement {suffix}: {error}"));
            }
        }

        assert!(matches!(
            store.authenticate_bearer(CapabilityBearerV1::from_bytes([0xA7; 32])),
            Err(SqliteGatewayErrorV1::StorageUnavailable)
        ));
        assert!(matches!(
            store.source_transfer_status(),
            Err(SqliteSourceTransferErrorV1::StorageUnavailable)
        ));
        assert!(matches!(
            store.initialize_canonical_metadata("must-not-commit", 1),
            Err(SqliteCanonicalMetadataInitializationErrorV1::StorageUnavailable)
        ));
        assert!(matches!(
            SqliteRoomStore::open(&source),
            Err(SqliteStoreOpenError::UnsafePath)
        ));

        drop(store);
        let replacement_store = SqliteRoomStore::open(&source)
            .unwrap_or_else(|error| panic!("open distinct replacement after release: {error}"));
        assert_eq!(replacement_store.database_identity(), replacement_identity);
        assert_ne!(replacement_store.database_identity(), original_identity);
        replacement_store
            .authenticate_bearer(CapabilityBearerV1::from_bytes([0xA7; 32]))
            .unwrap_or_else(|error| panic!("replacement authority remains intact: {error}"));
    }

    #[cfg(unix)]
    #[test]
    fn mid_command_parent_substitution_cannot_acknowledge_the_retained_commit() {
        let outer = tempdir().unwrap_or_else(|error| panic!("outer directory: {error}"));
        let requested_data_directory = outer.path().join("data");
        fs::create_dir(&requested_data_directory)
            .unwrap_or_else(|error| panic!("create data directory: {error}"));
        let data_directory = fs::canonicalize(&requested_data_directory)
            .unwrap_or_else(|error| panic!("canonical data directory: {error}"));
        let held_directory = data_directory.with_file_name("held-data");
        let database = data_directory.join("worldstream.sqlite3");
        let store = SqliteRoomStore::open(&database)
            .unwrap_or_else(|error| panic!("open retained source: {error}"));

        let hook_data_directory = data_directory.clone();
        let hook_held_directory = held_directory.clone();
        arm_writer_post_command_hook(&database, move || {
            fs::rename(&hook_data_directory, &hook_held_directory)?;
            fs::create_dir(&hook_data_directory)
        });

        assert!(matches!(
            store.initialize_canonical_metadata("deployment/unacknowledged", 7),
            Err(SqliteCanonicalMetadataInitializationErrorV1::StorageUnavailable)
        ));
        assert!(!database.exists());
        drop(store);

        let retained_database = held_directory.join("worldstream.sqlite3");
        let committed: (String, i64) = Connection::open(&retained_database)
            .and_then(|connection| {
                connection.query_row(
                    "SELECT deployment_lineage, storage_epoch \
                     FROM canonical_export_metadata WHERE metadata_id = 1",
                    (),
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
            })
            .unwrap_or_else(|error| panic!("inspect unacknowledged retained commit: {error}"));
        assert_eq!(committed, ("deployment/unacknowledged".to_owned(), 7));
    }

    #[test]
    fn writer_registry_never_reuses_a_path_for_another_file_identity() {
        let source = NamedTempFile::new().unwrap_or_else(|error| panic!("source: {error}"));
        let other = NamedTempFile::new().unwrap_or_else(|error| panic!("other: {error}"));
        let store = SqliteRoomStore::open(source.path())
            .unwrap_or_else(|error| panic!("open source: {error}"));
        let other_file = other
            .reopen()
            .unwrap_or_else(|error| panic!("retain other: {error}"));
        let other_identity = super::publication_file_identity(&other_file).map_or_else(
            |error| panic!("other identity: {error}"),
            super::public_sqlite_file_identity,
        );
        let path = super::normalized_path(source.path())
            .unwrap_or_else(|error| panic!("source path: {error}"));
        let result = SqliteRoomStore::open_with_retained_authority(
            path,
            other_file,
            other_identity,
            Arc::new(TestAuthorityClock::at("2026-08-15T12:00:10Z")),
            None,
        );
        assert!(matches!(result, Err(SqliteStoreOpenError::UnsafePath)));
        assert_ne!(store.database_identity(), other_identity);
    }

    #[test]
    fn opens_issued_v1_database_through_forward_authority_migration() {
        let file = NamedTempFile::new().unwrap_or_else(|error| panic!("temp DB: {error}"));
        let connection = Connection::open(file.path())
            .unwrap_or_else(|error| panic!("open v1 fixture: {error}"));
        connection
            .execute_batch(
                "CREATE TABLE IF NOT EXISTS schema_migrations (\
                 version INTEGER PRIMARY KEY, migration_id TEXT NOT NULL UNIQUE\
                 ) STRICT;",
            )
            .unwrap_or_else(|error| panic!("v1 migration table: {error}"));
        connection
            .execute_batch(INITIAL_MIGRATION_SCHEMA)
            .unwrap_or_else(|error| panic!("issued v1 schema: {error}"));
        connection
            .execute(
                "INSERT INTO schema_migrations(version, migration_id) VALUES (1, ?1)",
                [INITIAL_MIGRATION_ID],
            )
            .unwrap_or_else(|error| panic!("v1 migration identity: {error}"));
        connection
            .execute(
                "INSERT INTO authority_fences(\
                 witness_id, authenticated_principal, generation, scope_revocation_bytes, \
                 scope_revocation_hash, active) VALUES (?1, ?2, 1, ?3, ?4, 1)",
                params!["legacy-fence", PRINCIPAL, b"legacy-scope", [0xA5_u8; 32]],
            )
            .unwrap_or_else(|error| panic!("legacy authority fence: {error}"));
        let (prepared, _, _) = prepared_creation(0);
        let PreparedRoomWriteV1::Create(create) = prepared else {
            panic!("v1 fixture is a Room creation");
        };
        let persistence = create.persistence();
        let genesis_head = &persistence.complete_head;
        let trace_file =
            NamedTempFile::new().unwrap_or_else(|error| panic!("v1 transition trace DB: {error}"));
        let trace_store = SqliteRoomStore::open(trace_file.path())
            .unwrap_or_else(|error| panic!("open v1 transition trace SQLite: {error}"));
        let (mut transition_trace, _) = committed_trace(&trace_store);
        let transition = advance_conformance_replay_access_change(&mut transition_trace);
        assert_eq!(
            transition.previous_lineage_hash(),
            genesis_head.genesis_or_transition_hash()
        );
        let head = transition.complete_head();
        let room_id = head.room_id().to_string();
        connection
            .execute(
                "INSERT INTO rooms(\
                 room_id, room_status, room_seq, genesis_or_transition_hash, core_schema_version, \
                 pack_digest, core_state_hash, activity_state_hash, authoritative_state_hash, \
                 complete_head_bytes) VALUES (?1, 'active', ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
                params![
                    room_id,
                    i64::try_from(head.room_seq().get()).unwrap_or(-1),
                    head.genesis_or_transition_hash().to_string(),
                    head.core_schema_version(),
                    head.pack_digest().to_string(),
                    head.core_state_hash().to_string(),
                    head.activity_state_hash().to_string(),
                    head.authoritative_state_hash().to_string(),
                    head.canonical_bytes()
                        .unwrap_or_else(|error| panic!("v1 current Head bytes: {error}")),
                ],
            )
            .unwrap_or_else(|error| panic!("v1 Room: {error}"));
        connection
            .execute(
                "INSERT INTO room_genesis(room_id, pack_revision_lock_bytes, genesis_bytes) \
                 VALUES (?1, ?2, ?3)",
                params![
                    room_id,
                    persistence.canonical_pack_revision_lock_bytes,
                    persistence.canonical_genesis_bytes,
                ],
            )
            .unwrap_or_else(|error| panic!("v1 Genesis: {error}"));
        connection
            .execute(
                "INSERT INTO room_materializations(\
                 room_id, core_state_bytes, activity_state_bytes) VALUES (?1, ?2, ?3)",
                params![
                    room_id,
                    transition
                        .resulting_core_state()
                        .canonical_bytes()
                        .unwrap_or_else(|error| panic!("v1 resulting Core bytes: {error}")),
                    transition
                        .resulting_activity_state()
                        .to_bytes()
                        .unwrap_or_else(|error| panic!("v1 resulting Activity bytes: {error}")),
                ],
            )
            .unwrap_or_else(|error| panic!("v1 materializations: {error}"));
        for membership in transition.resulting_core_state().memberships().values() {
            let membership_json = serde_json::to_vec(membership)
                .unwrap_or_else(|error| panic!("encode v1 resulting Membership: {error}"));
            let membership_bytes = canonical(&membership_json)
                .to_bytes()
                .unwrap_or_else(|error| panic!("canonical v1 resulting Membership: {error}"));
            connection
                .execute(
                    "INSERT INTO room_members(\
                     room_id, member_id, principal_id, principal_kind, standing, access_mode, role, \
                     membership_bytes, frame_head) \
                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, 0)",
                    params![
                        room_id,
                        membership.member_id().to_string(),
                        membership.principal_id().to_string(),
                        super::principal_kind(membership.principal_kind()),
                        super::membership_standing(membership.standing()),
                        super::access_mode(membership.access_mode()),
                        membership.role(),
                        membership_bytes,
                    ],
                )
                .unwrap_or_else(|error| panic!("v1 Membership: {error}"));
        }
        connection
            .execute(
                "INSERT INTO transitions( \
                     room_id, transition_id, room_seq, transition_hash, previous_lineage_hash, \
                     core_schema_version, pack_digest, core_state_hash, activity_state_hash, \
                     authoritative_state_hash, transition_bytes \
                 ) VALUES (?1, ?2, 1, ?3, ?4, ?5, ?6, ?7, ?8, ?9, ?10)",
                params![
                    room_id,
                    "01ARZ3NDEKTSV4RRFFQ69G5FQ7",
                    transition.transition_hash().to_string(),
                    transition.previous_lineage_hash().to_string(),
                    head.core_schema_version(),
                    head.pack_digest().to_string(),
                    transition.resulting_core_state_hash().to_string(),
                    transition.resulting_activity_state_hash().to_string(),
                    transition.resulting_authoritative_state_hash().to_string(),
                    transition
                        .canonical_bytes()
                        .unwrap_or_else(|error| panic!("v1 Transition bytes: {error}")),
                ],
            )
            .unwrap_or_else(|error| panic!("v1 Membership-changing Transition: {error}"));
        connection
            .execute(
                "INSERT INTO room_integrity(room_id, status, generation) \
                 VALUES (?1, 'healthy', 1)",
                [&room_id],
            )
            .unwrap_or_else(|error| panic!("v1 integrity: {error}"));
        connection
            .execute(
                "UPDATE room_members SET frame_head = 4 \
                 WHERE room_id = ?1 AND member_id = ?2",
                params![ROOM, PARTICIPANT],
            )
            .unwrap_or_else(|error| panic!("seed unchanged v2 frame head: {error}"));
        drop(connection);

        let store = SqliteRoomStore::open(file.path())
            .unwrap_or_else(|error| panic!("forward-open v1 database: {error}"));
        let connection = Connection::open(file.path())
            .unwrap_or_else(|error| panic!("inspect migrated database: {error}"));
        let migrations = connection
            .prepare("SELECT version, migration_id FROM schema_migrations ORDER BY version")
            .and_then(|mut statement| {
                statement
                    .query_map((), |row| {
                        Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
                    })?
                    .collect::<rusqlite::Result<Vec<_>>>()
            })
            .unwrap_or_else(|error| panic!("migrated identities: {error}"));
        assert_eq!(
            migrations,
            [
                (1, INITIAL_MIGRATION_ID.to_owned()),
                (2, AUTHORITY_MIGRATION_ID.to_owned()),
                (3, OBSERVATION_MIGRATION_ID.to_owned()),
                (4, ACTIVATION_MIGRATION_ID.to_owned()),
                (5, SNAPSHOT_MIGRATION_ID.to_owned()),
                (6, CANONICAL_EXPORT_MIGRATION_ID.to_owned()),
                (7, MIGRATION_CHECKSUMS_MIGRATION_ID.to_owned()),
                (8, DEPLOYMENT_IDENTITIES_MIGRATION_ID.to_owned()),
                (9, TRANSFER_RECOVERY_COMPLETENESS_MIGRATION_ID.to_owned()),
                (10, TRANSFER_LIFECYCLE_MIGRATION_ID.to_owned()),
                (11, TRANSFER_BACKUP_IDENTITY_MIGRATION_ID.to_owned()),
                (12, EXTERNAL_INPUT_PREPARATION_MIGRATION_ID.to_owned()),
                (13, OBSERVATION_RETENTION_MIGRATION_ID.to_owned()),
                (14, SNAPSHOT_CADENCE_MIGRATION_ID.to_owned()),
                (15, ACTIVATION_BACKLOG_POLICY_MIGRATION_ID.to_owned()),
                (16, STREAM_TRANSFER_V2_MIGRATION_ID.to_owned()),
                (17, CHECKPOINT_OPERATIONAL_WITNESS_MIGRATION_ID.to_owned(),),
                (18, OPERATIONAL_HISTORY_ROOTS_MIGRATION_ID.to_owned(),),
                (19, CURRENT_TIMERS_MIGRATION_ID.to_owned(),),
                (20, CHECKPOINT_OPERATIONAL_WITNESS_V2_MIGRATION_ID.to_owned(),),
            ]
        );
        let retired: (String, String, i64, Vec<u8>, Vec<u8>, i64) = connection
            .query_row(
                "SELECT witness_id, authenticated_principal, generation, \
                 scope_revocation_bytes, scope_revocation_hash, active \
                 FROM retired_authority_fences_v1 WHERE witness_id = 'legacy-fence'",
                (),
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                        row.get(5)?,
                    ))
                },
            )
            .unwrap_or_else(|error| panic!("retired fence: {error}"));
        assert_eq!(retired.0, "legacy-fence");
        assert_eq!(retired.1, PRINCIPAL);
        assert_eq!(retired.2, 1);
        assert_eq!(retired.3, b"legacy-scope");
        assert_eq!(retired.4, [0xA5_u8; 32]);
        assert_eq!(retired.5, 1);
        let membership_generation_column: i64 = connection
            .query_row(
                "SELECT count(*) FROM pragma_table_info('room_members') \
                 WHERE name = 'membership_generation' AND type = 'INTEGER' \
                 AND \"notnull\" = 1 AND dflt_value = '1'",
                (),
                |row| row.get(0),
            )
            .unwrap_or_else(|error| panic!("membership generation column: {error}"));
        assert_eq!(membership_generation_column, 1);
        let migrated_generation: i64 = connection
            .query_row(
                "SELECT membership_generation FROM room_members \
                 WHERE room_id = ?1 AND member_id = ?2",
                params![ROOM, PARTICIPANT],
                |row| row.get(0),
            )
            .unwrap_or_else(|error| panic!("migrated Membership generation: {error}"));
        assert_eq!(migrated_generation, 2);
        let migrated_delivery: (i64, Option<i64>, Option<i64>) = connection
            .query_row(
                "SELECT retained_frame_floor, last_ack_frame_seq, reset_required_through \
                 FROM room_members WHERE room_id = ?1 AND member_id = ?2",
                params![ROOM, PARTICIPANT],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap_or_else(|error| panic!("migrated delivery positions: {error}"));
        assert_eq!(migrated_delivery, (1, None, Some(4)));
        let current_authority_rows: i64 = connection
            .query_row(
                "SELECT (SELECT count(*) FROM principals) \
                 + (SELECT count(*) FROM capabilities) + (SELECT count(*) FROM runners)",
                (),
                |row| row.get(0),
            )
            .unwrap_or_else(|error| panic!("current authority rows: {error}"));
        assert_eq!(current_authority_rows, 0);
        drop(store);
    }

    #[test]
    fn migration_failure_is_atomic_and_restart_retries_the_same_forward_prefix() {
        let file = NamedTempFile::new().unwrap_or_else(|error| panic!("temp DB: {error}"));
        let mut connection = Connection::open(file.path())
            .unwrap_or_else(|error| panic!("open interrupted migration fixture: {error}"));
        connection
            .execute_batch(
                "CREATE TABLE IF NOT EXISTS schema_migrations (\
                 version INTEGER PRIMARY KEY, migration_id TEXT NOT NULL UNIQUE\
                 ) STRICT;\
                 INSERT INTO schema_migrations(version, migration_id) VALUES \
                 (1, '0001-initial-storage-schema');\
                 ",
            )
            .unwrap_or_else(|error| panic!("migration ledger: {error}"));
        connection
            .execute_batch(INITIAL_MIGRATION_SCHEMA)
            .unwrap_or_else(|error| panic!("v1 schema: {error}"));
        connection
            .execute(
                "INSERT INTO rooms(\
                 room_id, room_status, room_seq, genesis_or_transition_hash, \
                 core_schema_version, pack_digest, core_state_hash, activity_state_hash, \
                 authoritative_state_hash, complete_head_bytes) \
                 VALUES ('room', 'active', 1, 'genesis', 'core', 'pack', 'core', 'activity', \
                 'authority', x'00')",
                (),
            )
            .unwrap_or_else(|error| panic!("malformed v1 Room: {error}"));
        connection
            .execute(
                "INSERT INTO room_members(\
                 room_id, member_id, principal_id, principal_kind, standing, access_mode, \
                 role, membership_bytes, frame_head) \
                 VALUES ('room', 'member', 'principal', 'human', 'enabled', 'participant', \
                 'member', x'00', 0)",
                (),
            )
            .unwrap_or_else(|error| panic!("malformed v1 Membership: {error}"));

        let failed = migrate(&mut connection);
        assert!(matches!(failed, Err(SqliteStoreOpenError::MigrationData)));
        let migration_rows: Vec<(i64, String)> = connection
            .prepare("SELECT version, migration_id FROM schema_migrations ORDER BY version")
            .and_then(|mut statement| {
                statement
                    .query_map((), |row| Ok((row.get(0)?, row.get(1)?)))?
                    .collect::<rusqlite::Result<Vec<_>>>()
            })
            .unwrap_or_else(|error| panic!("read rolled-back migration ledger: {error}"));
        assert_eq!(migration_rows, [(1, INITIAL_MIGRATION_ID.to_owned())]);
        let authority_table: Option<String> = connection
            .query_row(
                "SELECT name FROM sqlite_schema WHERE type = 'table' AND name = 'principals'",
                (),
                |row| row.get(0),
            )
            .optional()
            .unwrap_or_else(|error| panic!("inspect rolled-back migration: {error}"));
        assert_eq!(authority_table, None);

        connection
            .execute("DELETE FROM room_members WHERE room_id = 'room'", ())
            .unwrap_or_else(|error| panic!("repair v1 membership: {error}"));
        connection
            .execute("DELETE FROM rooms WHERE room_id = 'room'", ())
            .unwrap_or_else(|error| panic!("repair v1 Room: {error}"));
        migrate(&mut connection).unwrap_or_else(|error| panic!("restart migration: {error}"));
        let migration_count: i64 = connection
            .query_row("SELECT count(*) FROM schema_migrations", (), |row| {
                row.get(0)
            })
            .unwrap_or_else(|error| panic!("read restarted migration ledger: {error}"));
        assert_eq!(migration_count, 17);
    }

    #[test]
    fn transfer_lifecycle_upgrade_accepts_valid_v9_and_atomically_rejects_ambiguous_resources() {
        fn seed_v9(connection: &Connection) {
            connection
                .execute_batch(
                    "CREATE TABLE schema_migrations (\
                     version INTEGER PRIMARY KEY, migration_id TEXT NOT NULL UNIQUE\
                     ) STRICT;",
                )
                .unwrap_or_else(|error| panic!("v9 migration ledger: {error}"));
            let history = migration_history();
            for migration in &history[..9] {
                connection
                    .execute_batch(migration.sql)
                    .unwrap_or_else(|error| panic!("v9 schema {}: {error}", migration.id));
                if migration.version == 7 {
                    for prior in &history[..6] {
                        connection
                            .execute(
                                "UPDATE schema_migrations SET source_checksum = ?1 \
                                 WHERE version = ?2",
                                params![prior.checksum().to_string(), prior.version],
                            )
                            .unwrap_or_else(|error| {
                                panic!("v9 checksum backfill {}: {error}", prior.id)
                            });
                    }
                }
                let has_checksum = migration.version >= 7;
                if has_checksum {
                    connection
                        .execute(
                            "INSERT INTO schema_migrations(version, migration_id, source_checksum) \
                             VALUES (?1, ?2, ?3)",
                            params![
                                migration.version,
                                migration.id,
                                migration.checksum().to_string()
                            ],
                        )
                        .unwrap_or_else(|error| panic!("v9 ledger {}: {error}", migration.id));
                } else {
                    connection
                        .execute(
                            "INSERT INTO schema_migrations(version, migration_id) VALUES (?1, ?2)",
                            params![migration.version, migration.id],
                        )
                        .unwrap_or_else(|error| panic!("v9 ledger {}: {error}", migration.id));
                }
            }
        }

        let valid = NamedTempFile::new().unwrap_or_else(|error| panic!("valid v9 DB: {error}"));
        let mut valid_connection = Connection::open(valid.path())
            .unwrap_or_else(|error| panic!("open valid v9 DB: {error}"));
        seed_v9(&valid_connection);
        migrate(&mut valid_connection)
            .unwrap_or_else(|error| panic!("forward migrate valid v9 DB: {error}"));
        assert_eq!(
            super::read_source_transfer_status(&valid_connection)
                .unwrap_or_else(|error| panic!("valid migrated lifecycle: {error}"))
                .state(),
            SqliteSourceTransferStateV1::SourceAuthoritative
        );

        let ambiguous =
            NamedTempFile::new().unwrap_or_else(|error| panic!("ambiguous v9 DB: {error}"));
        let mut ambiguous_connection = Connection::open(ambiguous.path())
            .unwrap_or_else(|error| panic!("open ambiguous v9 DB: {error}"));
        seed_v9(&ambiguous_connection);
        for kind in ["artifact", "schema"] {
            ambiguous_connection
                .execute(
                    "INSERT INTO deployment_resource_identities \
                     (resource_kind, resource_identity, size_bytes, resource_digest) \
                     VALUES (?1, 'shared-resource', 1, ?2)",
                    params![kind, [0xA5_u8; 32].as_slice()],
                )
                .unwrap_or_else(|error| panic!("ambiguous resource identity: {error}"));
            ambiguous_connection
                .execute(
                    "INSERT INTO deployment_resource_blobs \
                     (resource_kind, resource_identity, resource_bytes, resource_digest) \
                     VALUES (?1, 'shared-resource', x'A5', ?2)",
                    params![kind, [0xA5_u8; 32].as_slice()],
                )
                .unwrap_or_else(|error| panic!("ambiguous resource bytes: {error}"));
        }
        assert!(matches!(
            migrate(&mut ambiguous_connection),
            Err(SqliteStoreOpenError::MigrationData)
        ));
        let migration_count: i64 = ambiguous_connection
            .query_row("SELECT count(*) FROM schema_migrations", (), |row| {
                row.get(0)
            })
            .unwrap_or_else(|error| panic!("ambiguous migration count: {error}"));
        assert_eq!(migration_count, 9);
        let lifecycle_exists: bool = ambiguous_connection
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE name = 'source_transfer_lifecycle')",
                (),
                |row| row.get(0),
            )
            .unwrap_or_else(|error| panic!("ambiguous lifecycle catalog: {error}"));
        assert!(!lifecycle_exists);
    }

    #[test]
    fn transfer_backup_identity_upgrade_rejects_active_v10_lifecycle_rows_atomically() {
        fn seed_v10(connection: &Connection) {
            connection
                .execute_batch(
                    "CREATE TABLE schema_migrations (\
                     version INTEGER PRIMARY KEY, migration_id TEXT NOT NULL UNIQUE\
                     ) STRICT;",
                )
                .unwrap_or_else(|error| panic!("v10 migration ledger: {error}"));
            let history = migration_history();
            for migration in &history[..10] {
                connection
                    .execute_batch(migration.sql)
                    .unwrap_or_else(|error| panic!("v10 schema {}: {error}", migration.id));
                if migration.version == 7 {
                    for prior in &history[..6] {
                        connection
                            .execute(
                                "UPDATE schema_migrations SET source_checksum = ?1 \
                                 WHERE version = ?2",
                                params![prior.checksum().to_string(), prior.version],
                            )
                            .unwrap_or_else(|error| {
                                panic!("v10 checksum backfill {}: {error}", prior.id)
                            });
                    }
                }
                if migration.version >= 7 {
                    connection
                        .execute(
                            "INSERT INTO schema_migrations(version, migration_id, source_checksum) \
                             VALUES (?1, ?2, ?3)",
                            params![
                                migration.version,
                                migration.id,
                                migration.checksum().to_string()
                            ],
                        )
                        .unwrap_or_else(|error| panic!("v10 ledger {}: {error}", migration.id));
                } else {
                    connection
                        .execute(
                            "INSERT INTO schema_migrations(version, migration_id) VALUES (?1, ?2)",
                            params![migration.version, migration.id],
                        )
                        .unwrap_or_else(|error| panic!("v10 ledger {}: {error}", migration.id));
                }
            }
        }

        for state in ["transfer_pending", "source_retired"] {
            let file =
                NamedTempFile::new().unwrap_or_else(|error| panic!("active v10 database: {error}"));
            let mut connection = Connection::open(file.path())
                .unwrap_or_else(|error| panic!("open active v10 database: {error}"));
            seed_v10(&connection);
            let (bundle_hash, target_fingerprint) = if state == "source_retired" {
                (Some([0xA5_u8; 32]), Some([0x5A_u8; 32]))
            } else {
                (None, None)
            };
            connection
                .execute(
                    "UPDATE source_transfer_lifecycle SET state = ?1, source_epoch = 1, \
                     target_epoch = 2, backup_path = 'legacy-transfer.sqlite3', \
                     backup_digest = ?2, bundle_hash = ?3, target_fingerprint = ?4 \
                     WHERE lifecycle_id = 1",
                    params![state, [0x11_u8; 32], bundle_hash, target_fingerprint],
                )
                .unwrap_or_else(|error| panic!("seed {state} lifecycle: {error}"));

            assert!(matches!(
                migrate(&mut connection),
                Err(SqliteStoreOpenError::MigrationData)
            ));
            let migration_count: i64 = connection
                .query_row("SELECT count(*) FROM schema_migrations", (), |row| {
                    row.get(0)
                })
                .unwrap_or_else(|error| panic!("{state} migration count: {error}"));
            assert_eq!(migration_count, 10);
            let identity_column_count: i64 = connection
                .query_row(
                    "SELECT count(*) FROM pragma_table_info('source_transfer_lifecycle') \
                     WHERE name IN ('backup_storage_id', 'backup_file_id')",
                    (),
                    |row| row.get(0),
                )
                .unwrap_or_else(|error| panic!("{state} identity columns: {error}"));
            assert_eq!(identity_column_count, 0);
        }
    }

    #[test]
    fn startup_rejects_retired_source_without_exact_bundle_and_target_witnesses() {
        let file = NamedTempFile::new().unwrap_or_else(|error| panic!("retired DB: {error}"));
        let store = SqliteRoomStore::open(file.path())
            .unwrap_or_else(|error| panic!("initialize retired DB: {error}"));
        drop(store);

        let connection = Connection::open(file.path())
            .unwrap_or_else(|error| panic!("open corrupt retired DB: {error}"));
        connection
            .pragma_update(None, "ignore_check_constraints", true)
            .unwrap_or_else(|error| panic!("disable fixture checks: {error}"));
        connection
            .execute(
                "UPDATE source_transfer_lifecycle SET state = 'source_retired', \
                 source_epoch = 7, target_epoch = 8, \
                 backup_path = '/verified/source.sqlite3', backup_digest = zeroblob(32), \
                 backup_storage_id = '0000000000000001', \
                 backup_file_id = '00000000000000000000000000000001', \
                 bundle_hash = NULL, target_fingerprint = NULL WHERE lifecycle_id = 1",
                (),
            )
            .unwrap_or_else(|error| panic!("seed corrupt retired state: {error}"));
        assert_eq!(
            super::read_source_transfer_status(&connection),
            Err(SqliteSourceTransferErrorV1::Corrupt)
        );
        drop(connection);

        match SqliteRoomStore::open(file.path()) {
            Err(
                SqliteStoreOpenError::SourceTransferState | SqliteStoreOpenError::IntegrityCheck(_),
            ) => {}
            Err(error) => panic!("unexpected corrupt-retired startup error: {error}"),
            Ok(_) => panic!("corrupt retired source unexpectedly opened"),
        }
    }

    #[test]
    fn native_migration_backup_is_published_verified_and_restorable() {
        let source = NamedTempFile::new().unwrap_or_else(|error| panic!("temp DB: {error}"));
        let connection = Connection::open(source.path())
            .unwrap_or_else(|error| panic!("open v1 backup fixture: {error}"));
        connection
            .execute_batch(
                "CREATE TABLE schema_migrations (\
                 version INTEGER PRIMARY KEY, migration_id TEXT NOT NULL UNIQUE\
                 ) STRICT;\
                 INSERT INTO schema_migrations(version, migration_id) VALUES \
                 (1, '0001-initial-storage-schema');\
                 ",
            )
            .unwrap_or_else(|error| panic!("v1 backup ledger: {error}"));
        connection
            .execute_batch(INITIAL_MIGRATION_SCHEMA)
            .unwrap_or_else(|error| panic!("v1 backup schema: {error}"));
        drop(connection);

        let before = Connection::open(source.path())
            .unwrap_or_else(|error| panic!("reopen v1 backup fixture: {error}"));
        let expected = native_migration_witness(&before)
            .unwrap_or_else(|error| panic!("source backup witness: {error:?}"));
        drop(before);
        let backup = publish_verified_migration_backup(source.path())
            .unwrap_or_else(|error| panic!("publish migration backup: {error:?}"));
        assert!(backup.is_file());
        let backup_connection = Connection::open(&backup)
            .unwrap_or_else(|error| panic!("open published migration backup: {error}"));
        assert_eq!(
            native_migration_witness(&backup_connection)
                .unwrap_or_else(|error| panic!("published backup witness: {error:?}")),
            expected
        );
        drop(backup_connection);

        let restore_dir = tempdir().unwrap_or_else(|error| panic!("restore directory: {error}"));
        let restored = restore_dir.path().join("restored.sqlite3");
        restore_verified_migration_backup(&backup, &restored)
            .unwrap_or_else(|error| panic!("restore migration backup: {error:?}"));
        let mut restored_connection = Connection::open(&restored)
            .unwrap_or_else(|error| panic!("open restored v1 database: {error}"));
        migrate(&mut restored_connection)
            .unwrap_or_else(|error| panic!("migrate restored database: {error}"));
        let restored_migrations: i64 = restored_connection
            .query_row("SELECT count(*) FROM schema_migrations", (), |row| {
                row.get(0)
            })
            .unwrap_or_else(|error| panic!("restored migration ledger: {error}"));
        assert_eq!(restored_migrations, 17);

        let startup_dir = tempdir().unwrap_or_else(|error| panic!("startup directory: {error}"));
        let startup = startup_dir.path().join("startup.sqlite3");
        restore_verified_migration_backup(&backup, &startup)
            .unwrap_or_else(|error| panic!("restore startup fixture: {error:?}"));
        let store = SqliteRoomStore::open(&startup)
            .unwrap_or_else(|error| panic!("startup migration with backup: {error}"));
        drop(store);
        let prefix = ".startup.sqlite3.worldstream-migration-backup.";
        let automatic_backups = fs::read_dir(startup_dir.path())
            .unwrap_or_else(|error| panic!("read startup directory: {error}"))
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| {
                        name.starts_with(prefix)
                            && !std::path::Path::new(name)
                                .extension()
                                .is_some_and(|extension| extension.eq_ignore_ascii_case("tmp"))
                    })
            })
            .collect::<Vec<_>>();
        assert_eq!(automatic_backups.len(), 1, "{automatic_backups:?}");
        let automatic_connection = Connection::open(&automatic_backups[0])
            .unwrap_or_else(|error| panic!("open automatic migration backup: {error}"));
        assert_eq!(
            native_migration_witness(&automatic_connection)
                .unwrap_or_else(|error| panic!("automatic backup witness: {error:?}")),
            expected
        );

        let mut interrupted = Connection::open(source.path())
            .unwrap_or_else(|error| panic!("open interruption fixture: {error}"));
        assert!(matches!(
            migrate_with_failpoint(&mut interrupted, Some(MigrationFailpoint::Authority)),
            Err(SqliteStoreOpenError::MigrationInterrupted {
                boundary: "after-authority-schema"
            })
        ));
        let authority_table: Option<String> = interrupted
            .query_row(
                "SELECT name FROM sqlite_schema WHERE type = 'table' AND name = 'principals'",
                (),
                |row| row.get(0),
            )
            .optional()
            .unwrap_or_else(|error| panic!("interrupted migration schema: {error}"));
        assert_eq!(authority_table, None);
        migrate(&mut interrupted)
            .unwrap_or_else(|error| panic!("restart after migration interruption: {error}"));
        drop(interrupted);
        let _ = fs::remove_file(backup);
    }

